pragma solidity ^0.8.25;

import { IComptroller } from "../Interfaces/IComptroller.sol";

/**
 * @title IEBrake
 * @author Venus Protocol
 * @notice Interface for the EBrake (Emergency Brake) contract.
 *         EBrake is an emergency action router that can only TIGHTEN restrictions,
 *         never loosen them. It also snapshots pre-incident values (CF, caps) so that
 *         governance can read and restore them via VIP. See resetCFSnapshot(),
 *         resetBorrowCapSnapshot() and resetSupplyCapSnapshot().
 *
 * @dev Design goals and integration patterns:
 *
 *   1. DIRECT ACCESS
 *      The Venus multisig is whitelisted. During an incident, the multisig can call
 *      any function here (pause, set caps, etc.) without going through governance.
 *
 *   2. ON-CHAIN MONITORING CONTRACTS
 *      Contracts like DeviationSentinel or any Venus monitoring contract are also whitelisted.
 *      They contain their own detection logic (e.g. price deviation checks) and call into EBrake
 *      when a threat is detected. Example: DeviationSentinel detects a price anomaly → calls
 *      EBrake.pauseSupply() or EBrake.decreaseCF(). The detection logic stays isolated in
 *      the monitor; EBrake only handles execution.
 *
 *   3. THIRD-PARTY MONITORS VIA SAFE MODULES
 *      External monitoring services (e.g. Hypernative) don't get direct whitelist access. Instead,
 *      for each service we create a dedicated Safe Module on our multisig. The Safe Module contains
 *      its own allowlist of which EBrake functions that service can call (e.g. Hypernative can only
 *      pause supply/borrow, not set caps). This keeps permission scoping outside of EBrake — each
 *      module enforces its own restrictions.
 *
 *   SAFETY INVARIANT — "Do no harm to existing users":
 *
 *      This contract can ONLY tighten restrictions, NEVER loosen them. If a whitelisted address
 *      is compromised, the worst outcome is a temporary freeze — never fund loss or liquidation.
 *
 *      This contract intentionally CANNOT:
 *        - Unpause             → EBrake can only pause, never unpause. Recovery is via governance VIP
 *        - Pause REPAY         → users must always be able to repay to avoid liquidation
 *        - Pause SEIZE         → liquidations must always work to prevent bad debt accumulation
 *        - Pause protocol      → setProtocolPaused blocks repay + liquidation, same problem
 *        - Lower LT            → lowering liquidation threshold would instantly make healthy
 *                                 positions liquidatable, harming innocent users
 *        - Increase caps       → caps can only be decreased to reduce exposure, never increased
 *        - Enable forced       → bypasses shortfall check entirely — ANY borrower becomes
 *          liquidation            liquidatable even with healthy collateral ratio
 *        - Target individual   → prevents griefing specific addresses via per-user forced
 *          users                  liquidation
 *        - Set close factor    → increasing allows liquidators to seize larger portions of
 *                                 collateral in one tx
 *        - Change oracle       → wrong oracle = mass mispricing = mass liquidations
 *        - Change liquidation  → altering incentive changes liquidation economics for all users
 *          incentive
 *
 *      Worst-case if EBrake is compromised:
 *        - Pauses minting/borrowing/redeeming/transfers (inconvenient, no fund loss)
 *        - Zeros supply/borrow caps (blocks new positions, existing ones unaffected)
 *        - Decreases collateral factor (blocks new borrows against asset, does NOT liquidate
 *          existing positions — that requires LT change, which EBrake cannot do)
 *        - Pauses flash loans (blocks flash loan attack vector, no user impact)
 *        - Pauses the Liquidity Hub (blocks deposits and redemptions; existing balances
 *          untouched, and emergencyReallocate still works)
 *        - Pauses a Hub YieldGroup or one of its resources (stops new deposits routing there, and
 *          user withdrawals skip it; the balance already there still counts toward NAV)
 *      Recovery: Governance VIP restores all parameters. Temporary freeze, not catastrophic.
 *
 *   BSC vs NON-BSC DIFFERENCES:
 *
 *      The IS_REMOTE_CHAIN immutable determines which comptroller ABI is used for COMPTROLLER
 *      (see OTHER COMPTROLLERS for markets of other comptrollers).
 *      It is set at deployment and cannot be changed.
 *
 *      BSC (BNB Chain) — Diamond Comptroller (IS_REMOTE_CHAIN = false):
 *        - decreaseCF(market, newCF) — for markets of COMPTROLLER, iterates corePoolId to lastPoolId,
 *          applies newCF only to pools where currentCF > newCF; silently skips pools already at or
 *          below newCF.
 *        - decreaseCF(market, poolId, newCF) — targets a single pool (e.g. multisig use)
 *        - Uses poolMarkets() (7-value return) to read LT,
 *          calls setCollateralFactor(poolId, market, newCF, LT) which returns uint256 error code
 *        - Supports e-mode pools via poolId > 0
 *        - pauseFlashLoan() — flash loans only exist on Diamond
 *        - pauseHub(hub), pauseHubYieldGroup(yieldGroup), pauseHubResource(yieldGroup, resource)
 *          — the Liquidity Hub is BSC-only
 *        - disablePoolBorrow(poolId, market) — per-pool granular borrow disable, only on Diamond
 *        - revokeFlashLoanAccess(account) — remove a single account from the flash loan
 *          whitelist; flash loan whitelist only exists on Diamond
 *        - ACM permission strings use underscore prefix:
 *          _setActionsPaused, _setMarketBorrowCaps, _setMarketSupplyCaps
 *
 *      Non-BSC chains — IL Comptroller (IS_REMOTE_CHAIN = true):
 *        - decreaseCF(market, newCF) — uses markets() (3-value return) to read LT,
 *          calls setCollateralFactor(market, newCF, LT) which returns void (no error code).
 *          Reverts if newCF > currentCF.
 *        - No poolId concept — only the core pool exists (other pools are deprecated)
 *        - decreaseCF(market, poolId, newCF) not granted ACM permission (no pool concept on IL)
 *        - pauseFlashLoan() not granted ACM permission (flash loans don't exist on IL)
 *        - pauseHub(address), pauseHubYieldGroup(address) and
 *          pauseHubResource(address,address) not granted ACM permission (no Liquidity Hub off BSC).
 *          These are EBrake's own roles; what EBrake must hold on the Hub side is `pauseHub()` and
 *          `pauseYieldGroup(address)` on the Hub, and `pauseResource(address)` on each YieldGroup.
 *        - ACM permission strings have no underscore:
 *          setActionsPaused, setMarketBorrowCaps, setMarketSupplyCaps
 *
 *      All other functions (pauseActions, pauseSupply, pauseBorrow, pauseRedeem,
 *      pauseTransfer, setMarketBorrowCaps, setMarketSupplyCaps) are ABI-compatible
 *      across both comptroller types and work identically on all chains.
 *
 *   OTHER COMPTROLLERS (e.g. SPOKE POOLS):
 *
 *      The per-market functions (pauseActions, pauseSupply, pauseRedeem, pauseBorrow, pauseTransfer,
 *      decreaseCF(address,uint256), setMarketBorrowCaps, setMarketSupplyCaps) act on market.comptroller(),
 *      whoever the caller is.
 *        - For a market of a comptroller other than COMPTROLLER (Spoke pools run the isolated-pools
 *          codebase), decreaseCF(address,uint256) uses the IL ABI with pool id 0, whatever IS_REMOTE_CHAIN
 *          says. The pause and cap functions have the same ABI on both comptroller types.
 *        - EBrake can only act on a comptroller once governance grants EBrake these ACM permissions on it
 *          (no underscore prefix, uint256[] actions): setActionsPaused(address[],uint256[],bool),
 *          setCollateralFactor(address,uint256,uint256), setMarketBorrowCaps(address[],uint256[]) and
 *          setMarketSupplyCaps(address[],uint256[]). These grants decide which comptrollers EBrake reaches.
 *        - All markets of a batch must share one comptroller, otherwise the call reverts with
 *          MarketsOnDifferentComptrollers.
 *      Each ACM permission on EBrake covers every comptroller EBrake reaches. Callers that should only act on
 *      some pools check the market themselves.
 *      resetCFSnapshot picks its path the same way as decreaseCF(address,uint256).
 *      The Diamond-only functions (pauseFlashLoan, disablePoolBorrow, revokeFlashLoanAccess,
 *      decreaseCF(address,uint96,uint256)) only ever act on COMPTROLLER.
 *      Snapshots are keyed by market address, so Core and Spoke markets never share an entry.
 */
interface IEBrake {
    // ═══════════════════════════════════════════════════════════════════════
    //                              EVENTS
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Emitted when actions are paused on markets via batch pause.
    /// @param caller The address that triggered the emergency action.
    /// @param markets The vToken market addresses that were paused.
    /// @param actions The actions that were paused.
    event ActionsPaused(address indexed caller, address[] markets, IComptroller.Action[] actions);

    /// @notice Emitted when a single action is paused on a market.
    /// @param caller The address that triggered the emergency action.
    /// @param market The vToken market address that was paused.
    /// @param action The action that was paused.
    event ActionPaused(address indexed caller, address indexed market, IComptroller.Action action);

    /// @notice Emitted when flash loans are paused.
    /// @param caller The address that triggered the emergency action.
    event FlashLoanPaused(address indexed caller);

    /// @notice Emitted when borrowing is disabled for a market in a specific pool.
    /// @param caller The address that triggered the emergency action.
    /// @param poolId The pool identifier (0 = core pool, >0 = e-mode pools).
    /// @param market The vToken market address whose pool-borrow flag was disabled.
    event PoolBorrowDisabled(address indexed caller, uint96 indexed poolId, address indexed market);

    /// @notice Emitted when an account is removed from the flash loan whitelist.
    /// @param caller The address that triggered the emergency action.
    /// @param account The account whose flash loan access was revoked.
    event FlashLoanAccessRevoked(address indexed caller, address indexed account);

    /// @notice Emitted when a collateral factor is decreased.
    ///         Used for both core/e-mode pools and IL comptrollers.
    /// @param caller The address that triggered the emergency action.
    /// @param market The vToken market address whose CF was decreased.
    /// @param poolId The pool ID. On BNB Chain (Diamond comptroller) this identifies the core pool (0)
    ///        or an e-mode pool (>0). IL comptrollers (non-BSC chains, Spoke pools) have no pool concept,
    ///        so 0 is used.
    /// @param newCF The new collateral factor value that the market was set to.
    event CollateralFactorDecreased(
        address indexed caller,
        address indexed market,
        uint96 indexed poolId,
        uint256 newCF
    );

    /// @notice Emitted when borrow caps are decreased.
    /// @param caller The address that triggered the emergency action.
    /// @param markets The vToken market addresses whose borrow caps were decreased.
    /// @param newBorrowCaps The new borrow cap values.
    event BorrowCapsDecreased(address indexed caller, address[] markets, uint256[] newBorrowCaps);

    /// @notice Emitted when supply caps are decreased.
    /// @param caller The address that triggered the emergency action.
    /// @param markets The vToken market addresses whose supply caps were decreased.
    /// @param newSupplyCaps The new supply cap values.
    event SupplyCapsDecreased(address indexed caller, address[] markets, uint256[] newSupplyCaps);

    /// @notice Emitted when a market's CF/LT snapshot is reset after governance recovery.
    /// @param market The market address whose CF snapshot was cleared.
    event CFSnapshotReset(address indexed market);

    /// @notice Emitted when a market's borrow cap snapshot is reset after governance recovery.
    /// @param market The market address whose borrow cap snapshot was cleared.
    event BorrowCapSnapshotReset(address indexed market);

    /// @notice Emitted when a market's supply cap snapshot is reset after governance recovery.
    /// @param market The market address whose supply cap snapshot was cleared.
    event SupplyCapSnapshotReset(address indexed market);

    /// @notice Emitted when the Liquidity Hub was paused through EBrake.
    /// @param caller The address that triggered the pause.
    /// @param hub The Hub that was paused.
    event HubPaused(address indexed caller, address indexed hub);

    /// @notice Emitted when a Hub YieldGroup was paused through EBrake.
    /// @param caller The address that triggered the pause.
    /// @param hub The Hub the YieldGroup belongs to.
    /// @param yieldGroup The YieldGroup that was paused.
    event HubYieldGroupPaused(address indexed caller, address indexed hub, address indexed yieldGroup);

    /// @notice Emitted when a resource inside a Hub YieldGroup was paused through EBrake.
    /// @param caller The address that triggered the pause.
    /// @param yieldGroup The YieldGroup that holds the resource.
    /// @param resource The resource that was paused.
    event HubResourcePaused(address indexed caller, address indexed yieldGroup, address indexed resource);

    // ═══════════════════════════════════════════════════════════════════════
    //                              ERRORS
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Thrown when a forbidden action (REPAY, SEIZE, etc.) is passed to batch pause.
    /// @param action The disallowed action that was passed.
    error ForbiddenAction(IComptroller.Action action);

    /// @notice Thrown when a zero address is passed where a valid address is required.
    error ZeroAddress();

    /// @notice Thrown when a market is not listed in the given pool.
    ///         On BNB Chain (Diamond comptroller) poolId identifies the core pool (0) or an e-mode pool (>0).
    ///         IL comptrollers (non-BSC chains, Spoke pools) have no pool concept, so poolId is 0.
    /// @param poolId The pool ID that was queried.
    /// @param market The market address that is not listed.
    error MarketNotListed(uint96 poolId, address market);

    /// @notice Thrown when setCollateralFactor returns a non-zero error code.
    /// @param errorCode The error code returned by the comptroller.
    error SetCollateralFactorFailed(uint256 errorCode);

    /// @notice Thrown when an empty array is passed where at least one element is required.
    error EmptyArray();

    /// @notice Thrown when array lengths do not match.
    /// @param expected The expected array length.
    /// @param actual The actual array length.
    error ArrayLengthMismatch(uint256 expected, uint256 actual);

    /// @notice Thrown when the requested cap exceeds the current cap on the comptroller.
    /// @param market The market whose cap was attempted to be increased.
    /// @param currentCap The current cap value on the comptroller.
    /// @param requestedCap The new cap value that was rejected.
    error CapExceedsCurrent(address market, uint256 currentCap, uint256 requestedCap);

    /// @notice Thrown when a function is called that is not supported on remote chains (IS_REMOTE_CHAIN).
    ///         Pool ID is a Diamond-only concept — this function should never be ACM-granted on IL chains.
    error NotSupportedOnRemoteChain();

    /// @notice Thrown when the requested collateral factor exceeds the current CF on the comptroller.
    ///         EBrake can only tighten CF — newCF must be <= currentCF.
    /// @param market The market whose CF was attempted to be increased.
    /// @param poolId The pool ID where the violation was detected (0 on IL comptroller).
    /// @param currentCF The current collateral factor on the comptroller.
    /// @param requestedCF The new CF value that was rejected.
    error CFExceedsCurrent(address market, uint96 poolId, uint256 currentCF, uint256 requestedCF);

    /// @notice Thrown when a batch mixes markets of different comptrollers.
    /// @param expected The comptroller of the first market in the batch.
    /// @param actual The comptroller of the first market that differs from it.
    error MarketsOnDifferentComptrollers(address expected, address actual);

    // ═══════════════════════════════════════════════════════════════════════
    //                     EMERGENCY ACTIONS — BATCH OPERATIONS
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Pause multiple actions on multiple markets in one call.
     * @dev Only MINT, REDEEM, BORROW, and TRANSFER are allowed. Reverts on REPAY, SEIZE,
     *      LIQUIDATE, ENTER_MARKET, or EXIT_MARKET — see SAFETY INVARIANT.
     * @param markets The vToken market addresses to pause actions on.
     * @param actions The actions to pause.
     */
    function pauseActions(address[] calldata markets, IComptroller.Action[] calldata actions) external;

    // ═══════════════════════════════════════════════════════════════════════
    //                     EMERGENCY ACTIONS — SINGLE MARKET PAUSING
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Pause supply (mint) on a single market.
    ///         Blocks new deposits. Existing suppliers can still redeem.
    /// @param market The vToken market address.
    function pauseSupply(address market) external;

    /// @notice Pause redeem on a single market.
    ///         Blocks withdrawals. Use when draining must be stopped immediately.
    /// @param market The vToken market address.
    function pauseRedeem(address market) external;

    /// @notice Pause borrow on a single market.
    ///         Blocks new borrows. Existing borrowers can still repay.
    /// @param market The vToken market address.
    function pauseBorrow(address market) external;

    /// @notice Pause transfer of vTokens on a single market.
    ///         Blocks vToken movement, prevents attacker from moving stolen collateral.
    /// @param market The vToken market address.
    function pauseTransfer(address market) external;

    // ═══════════════════════════════════════════════════════════════════════
    //                     EMERGENCY ACTIONS — FLASH LOANS
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Pause flash loans across the core pool.
    function pauseFlashLoan() external;

    /**
     * @notice Disable borrowing for a market in a specific pool, leaving other pools unaffected.
     * @dev Only meaningful on Diamond comptroller (BSC) where the per-pool `isBorrowAllowed` flag exists.
     *      On non-BSC chains the underlying call will revert (selector mismatch on IL comptroller).
     *
     *      This is independent of `pauseBorrow(market)` which flips the global
     *      `_actionPaused[market][BORROW]` flag across every pool. Both flags must allow borrowing
     *      for borrows to actually proceed in a given pool/market — recovery from a combined
     *      tightening therefore requires governance to clear both flags.
     *
     *      The boolean argument is hardcoded to `false` inside the implementation to preserve
     *      the EBrake "tighten only, never loosen" invariant. Re-enabling borrow is governance-only.
     * @param poolId The pool identifier (0 = core pool, >0 = e-mode pools).
     * @param market The vToken market address.
     */
    function disablePoolBorrow(uint96 poolId, address market) external;

    /**
     * @notice Remove a single account from the flash loan whitelist.
     * @dev Only meaningful on Diamond comptroller (BSC) where the flash loan whitelist exists.
     *      On non-BSC chains the underlying call will revert (selector mismatch on IL comptroller).
     *
     *      This is the surgical alternative to `pauseFlashLoan()`, which kills flash loans for
     *      every whitelisted account. Use it when a single whitelisted integrator is compromised.
     *
     *      The boolean argument is hardcoded to `false` inside the implementation to preserve
     *      the EBrake "tighten only, never loosen" invariant. Re-granting access is governance-only.
     *
     *      Idempotent: if the account is not currently whitelisted, the call is a no-op and
     *      no event is emitted. FlashLoanAccessRevoked is a true state-change signal.
     * @param account The account whose flash loan access should be revoked.
     */
    function revokeFlashLoanAccess(address account) external;

    // ═══════════════════════════════════════════════════════════════════════
    //                     EMERGENCY ACTIONS — LIQUIDITY HUB
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Pause the Liquidity Hub, halting deposits and redemptions.
     * @dev Forwards to the Hub, which EBrake holds the `pauseHub()` ACM role on. Tighten-only —
     *      unpausing is a VIP against the Hub directly. An already-paused Hub is a no-op with no
     *      event, so {HubPaused} stays a true state-change signal, as {pauseFlashLoan} does.
     * @param hub The Liquidity Hub to pause.
     */
    function pauseHub(address hub) external;

    /**
     * @notice Stop a Hub routing new deposits to one YieldGroup. The balance already there still
     *         counts toward NAV, but user withdrawals skip it until governance unpauses it.
     * @dev Forwards to the Hub the YieldGroup reports through `hub()`, which EBrake holds the
     *      `pauseYieldGroup(address)` ACM role on. Tighten-only, and an already-paused YieldGroup is
     *      a no-op with no event, as {pauseHub}. A YieldGroup the Hub never registered reads as
     *      unpaused, so the Hub's own `YieldGroupNotRegistered` revert comes back to the caller —
     *      which is also what stops a fake YieldGroup that names a real Hub.
     * @param yieldGroup The YieldGroup to pause.
     */
    function pauseHubYieldGroup(address yieldGroup) external;

    /**
     * @notice Stop a Hub YieldGroup routing new deposits to one of its resources. The balance
     *         already there still counts toward NAV, but user withdrawals skip it until governance
     *         unpauses it.
     * @dev Forwards to the YieldGroup, which checks `pauseResource(address)` against its own
     *      address, so EBrake needs that grant on every YieldGroup it should reach. Tighten-only,
     *      and an already-paused resource is a no-op with no event, as {pauseHub}. A resource the
     *      YieldGroup never registered reads as unpaused, so its `ResourceNotRegistered` revert
     *      comes back to the caller.
     * @param yieldGroup The YieldGroup that holds the resource.
     * @param resource The resource to pause.
     */
    function pauseHubResource(address yieldGroup, address resource) external;

    // ═══════════════════════════════════════════════════════════════════════
    //                     EMERGENCY ACTIONS — RISK PARAMETER ADJUSTMENTS
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Decrease collateral factor to `newCF` for a market across all relevant pools.
     *         Liquidation threshold is left unchanged.
     *         Blocks/limits new borrows against the asset. Does NOT make existing positions liquidatable —
     *         that would require lowering LT, which this contract cannot do.
     * @dev On the Diamond (markets of COMPTROLLER, IS_REMOTE_CHAIN=false): iterates corePoolId to lastPoolId;
     *      applies `newCF` only to pools where currentCF > newCF (silently skips pools already
     *      at or below newCF and unlisted pools). Never reverts due to CF comparison — use the
     *      per-pool overload if you need strict enforcement on a specific pool.
     *      On an IL comptroller (IS_REMOTE_CHAIN=true, or a market of another comptroller such as a
     *      Spoke pool): applies to the single market entry with pool id 0 and
     *      reverts with CFExceedsCurrent if newCF > currentCF.
     * @param market The vToken market address whose CF should be decreased.
     * @param newCF The new collateral factor value. On Diamond, pools already at or below this
     *              value are silently skipped. On IL, must be <= current CF.
     */
    function decreaseCF(address market, uint256 newCF) external;

    /**
     * @notice Decrease collateral factor to `newCF` for a market in a specific pool.
     *         Same safety guarantees as decreaseCF(address,uint256) — LT is left unchanged.
     * @dev Only meaningful on Diamond comptroller (BSC) where multiple pools exist.
     *      Reverts with NotSupportedOnRemoteChain on IL chains — ACM must not grant this permission there.
     *      Reverts with CFExceedsCurrent if newCF > current CF in the targeted pool.
     * @param market The vToken market address whose CF should be decreased.
     * @param poolId The pool ID (0 for core pool, >0 for e-mode pools).
     * @param newCF The new collateral factor value. Must be <= current CF in the targeted pool.
     */
    function decreaseCF(address market, uint96 poolId, uint256 newCF) external;

    /**
     * @notice Decrease borrow caps on markets. Each new cap must be strictly LOWER than the current value.
     *         Elements equal to the current cap are silently skipped. Setting to 0 blocks all new borrows.
     *         Existing borrows are never affected by caps.
     * @param markets The vToken market addresses to adjust borrow caps on.
     * @param newBorrowCaps The new borrow cap values. Each must be < current cap (equality is a no-op, > reverts).
     */
    function setMarketBorrowCaps(address[] calldata markets, uint256[] calldata newBorrowCaps) external;

    /**
     * @notice Decrease supply caps on markets. Each new cap must be strictly LOWER than the current value.
     *         Elements equal to the current cap are silently skipped. Setting to 0 blocks all new deposits.
     *         Existing deposits are never affected by caps.
     * @param markets The vToken market addresses to adjust supply caps on.
     * @param newSupplyCaps The new supply cap values. Each must be < current cap (equality is a no-op, > reverts).
     */
    function setMarketSupplyCaps(address[] calldata markets, uint256[] calldata newSupplyCaps) external;

    // ═══════════════════════════════════════════════════════════════════════
    //                     MARKET STATE SNAPSHOT — RESET & VIEW
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Reset only the stored CF/LT snapshot for a market.
     * @dev Called by governance as part of a recovery VIP after restoring collateral factors.
     *      Clears per-pool CF/LT values so that future EBrake actions can capture fresh
     *      pre-incident values. Does not touch cap snapshots.
     *      For a market of COMPTROLLER on the Diamond it clears pool ids corePoolId to lastPoolId; for any other
     *      market, pool id 0.
     * @param market The vToken market address whose CF snapshot should be cleared.
     */
    function resetCFSnapshot(address market) external;

    /**
     * @notice Reset only the stored borrow cap snapshot for a market.
     * @dev Called by governance as part of a recovery VIP after restoring the borrow cap.
     *      Clears borrowCap and borrowCapSnapshotted so that future EBrake actions can capture
     *      a fresh pre-incident value. Does not touch the supply cap or CF snapshots.
     * @param market The vToken market address whose borrow cap snapshot should be cleared.
     */
    function resetBorrowCapSnapshot(address market) external;

    /**
     * @notice Reset only the stored supply cap snapshot for a market.
     * @dev Called by governance as part of a recovery VIP after restoring the supply cap.
     *      Clears supplyCap and supplyCapSnapshotted so that future EBrake actions can capture
     *      a fresh pre-incident value. Does not touch the borrow cap or CF snapshots.
     * @param market The vToken market address whose supply cap snapshot should be cleared.
     */
    function resetSupplyCapSnapshot(address market) external;

    /**
     * @notice Read the stored collateral factor and liquidation threshold snapshot for a market in a specific pool.
     * @param market The vToken market address.
     * @param poolId The pool ID (0 for IL comptrollers, including Spoke pools, or the core pool on Diamond).
     * @return cf The collateral factor that was stored before EBrake zeroed it. 0 if no snapshot exists.
     * @return lt The liquidation threshold at the time of the snapshot. 0 if no snapshot exists.
     */
    function getMarketCFSnapshot(address market, uint96 poolId) external view returns (uint256 cf, uint256 lt);
}
","keccak256":"0x797fc325e8cff141068cb153b19b1567b134be124b0b16586a60d6a422b1678e","license":"BSD-3-Clause"},"contracts/Interfaces/IBStockToken.sol":{"content":"// SPDX-License-Identifier: BSD-3-Clause
pragma solidity ^0.8.25;

/**
 * @title IBStockToken
 * @author Venus
 * @notice Minimal interface of a bStock token (tokenized equity) used by Venus.
 * @dev Each bStock checks its PauseManager before every transfer, and the issuer can repoint it
 *      (setPauseManager), so different bStocks may use different PauseManagers.
 *      It also checks every party to a transfer against its compliance module, which the issuer can repoint
 *      (setCompliance) too.
 */
interface IBStockToken {
    /// @notice Returns the PauseManager the token checks before every transfer
    /// @return The PauseManager address
    function pauseManager() external view returns (address);

    /// @notice Returns the compliance module the token checks every party to a transfer against
    /// @return The compliance module address
    function compliance() external view returns (address);
}
","keccak256":"0x49e307aaecbd6c8643fb02bbe3285562afd4786cf84d54cb2bce7fade22461bb","license":"BSD-3-Clause"},"contracts/Interfaces/ICompliance.sol":{"content":"// SPDX-License-Identifier: BSD-3-Clause
pragma solidity ^0.8.25;

/**
 * @title ICompliance
 * @author Venus
 * @notice Minimal interface of the bStock issuer's compliance module (BSC: 0x53dBa7AaBDe774787A1F57236B235567dA8e14F4).
 *         A bStock runs checkIsCompliant on every party to a transfer, so a sanctioned or blocklisted address can
 *         neither send nor receive the token.
 */
interface ICompliance {
    /// @notice Reverts if an account may not be a party to a transfer of a token
    /// @dev Reverts with UserSanctioned() for a sanctioned account and UserBlocked() for one blocklisted for the token
    /// @param token The token being transferred
    /// @param account The account to check
    function checkIsCompliant(address token, address account) external view;
}
","keccak256":"0xea86ed00bbb16e7292a257182b0cb2cad5ba842f85d36e24877b2f8f234cc74c","license":"BSD-3-Clause"},"contracts/Interfaces/IComptroller.sol":{"content":"// SPDX-License-Identifier: BSD-3-Clause
pragma solidity ^0.8.25;

import { ResilientOracleInterface } from "@venusprotocol/oracle/contracts/interfaces/OracleInterface.sol";
import { IVToken } from "./IVToken.sol";

/// @title IComptroller
/// @author Venus Protocol
/// @notice Interface for the Venus Comptroller with market management and risk parameter functions.
interface IComptroller {
    enum Action {
        MINT,
        REDEEM,
        BORROW,
        REPAY,
        SEIZE,
        LIQUIDATE,
        TRANSFER,
        ENTER_MARKET,
        EXIT_MARKET
    }

    /// @notice Pause or unpause specific actions on given markets.
    /// @param markets_ The list of vToken market addresses.
    /// @param actions_ The list of actions to pause/unpause.
    /// @param paused_ True to pause, false to unpause.
    function setActionsPaused(address[] calldata markets_, Action[] calldata actions_, bool paused_) external;

    /// @notice Set borrow caps for the given markets.
    /// @param vTokens The list of vToken market addresses.
    /// @param newBorrowCaps The list of new borrow cap values.
    function setMarketBorrowCaps(address[] calldata vTokens, uint256[] calldata newBorrowCaps) external;

    /// @notice Set supply caps for the given markets.
    /// @param vTokens The list of vToken market addresses.
    /// @param newSupplyCaps The list of new supply cap values.
    function setMarketSupplyCaps(address[] calldata vTokens, uint256[] calldata newSupplyCaps) external;

    /// @notice Unlist a market from the comptroller.
    /// @param vToken The vToken market address to unlist.
    /// @return uint256 Error code (0 = success).
    function unlistMarket(address vToken) external returns (uint256);

    /// @notice Execute a flash loan.
    /// @param onBehalf The address on whose behalf the flash loan is executed.
    /// @param receiver The address receiving the flash loan funds.
    /// @param vTokens The list of vToken markets to borrow from.
    /// @param underlyingAmounts The list of underlying amounts to borrow.
    /// @param param Additional parameters for the flash loan callback.
    function executeFlashLoan(
        address payable onBehalf,
        address payable receiver,
        IVToken[] memory vTokens,
        uint256[] memory underlyingAmounts,
        bytes memory param
    ) external;

    /// @notice Enter multiple markets to use as collateral.
    /// @param vTokens The list of vToken market addresses to enter.
    /// @return uint256[] Error codes for each market (0 = success).
    function enterMarkets(address[] calldata vTokens) external returns (uint256[] memory);

    /// @notice Enter a market on behalf of another address.
    /// @param onBehalf The address to enter the market for.
    /// @param vToken The vToken market address.
    /// @return uint256 Error code (0 = success).
    function enterMarketBehalf(address onBehalf, address vToken) external returns (uint256);

    /// @notice Enter a market for a specific user (internal comptroller use).
    /// @param user The user address.
    /// @param vToken The vToken market address.
    /// @return uint256 Error code (0 = success).
    function enterMarket(address user, address vToken) external returns (uint256);

    /// @notice Enter a market for an account. The caller needs the ACM permission for `enterMarketForAccount(address,address)`.
    /// @param account The account to enter the market for.
    /// @param vToken The vToken market address.
    /// @return uint256 Error code (0 = success).
    function enterMarketForAccount(address account, address vToken) external returns (uint256);

    /// @notice Check whether an action is paused on a given market.
    /// @param market The vToken market address.
    /// @param action The action to check.
    /// @return bool True if the action is paused.
    function actionPaused(address market, Action action) external view returns (bool);

    /// @notice Get market information for a given vToken.
    /// @param vToken The vToken market address.
    /// @return isListed Whether the market is listed.
    /// @return collateralFactorMantissa The collateral factor mantissa.
    /// @return isComped Whether the market receives COMP/XVS rewards.
    function markets(
        address vToken
    ) external view returns (bool isListed, uint256 collateralFactorMantissa, bool isComped);

    /// @notice Get the price oracle used by the comptroller.
    /// @return ResilientOracleInterface The oracle contract.
    function oracle() external view returns (ResilientOracleInterface);

    /// @notice Check if an account has entered a given market.
    /// @param account The account address.
    /// @param vToken The vToken market to check membership for.
    /// @return bool True if the account is a member of the market.
    function checkMembership(address account, IVToken vToken) external view returns (bool);

    /// @notice Get the borrowing power of an account.
    /// @param account The account address.
    /// @return error Error code (0 = success).
    /// @return liquidity The account's excess liquidity.
    /// @return shortfall The account's shortfall.
    function getBorrowingPower(
        address account
    ) external view returns (uint256 error, uint256 liquidity, uint256 shortfall);

    /// @notice Get an account's liquidity as it would be after redeeming or borrowing in one market.
    /// @param account The account address.
    /// @param vTokenModify The vToken market the redeem or borrow applies to.
    /// @param redeemTokens The amount of vTokens to redeem.
    /// @param borrowAmount The amount of underlying to borrow.
    /// @return error Error code (0 = success).
    /// @return liquidity The account's excess liquidity.
    /// @return shortfall The account's shortfall.
    function getHypotheticalAccountLiquidity(
        address account,
        address vTokenModify,
        uint256 redeemTokens,
        uint256 borrowAmount
    ) external view returns (uint256 error, uint256 liquidity, uint256 shortfall);

    /// @notice Get the treasury fee percentage.
    /// @return uint256 The treasury percentage mantissa.
    function treasuryPercent() external view returns (uint256);

    /// @notice Get the borrow cap for a given market.
    /// @param vToken The vToken market address.
    /// @return uint256 The borrow cap.
    function borrowCaps(address vToken) external view returns (uint256);

    /// @notice Get the supply cap for a given market.
    /// @param vToken The vToken market address.
    /// @return uint256 The supply cap.
    function supplyCaps(address vToken) external view returns (uint256);

    /// @notice Check if a delegate is approved to borrow on behalf of a borrower.
    /// @param borrower The borrower address.
    /// @param delegate The delegate address.
    /// @return bool True if the delegate is approved.
    function approvedDelegates(address borrower, address delegate) external view returns (bool);

    function getAccountLiquidity(address account) external view returns (uint256, uint256, uint256);

    function exitMarket(address vToken) external returns (uint256);

    function updateDelegate(address delegate, bool approved) external;
}
